```javascript
/**
 * RPG combat: a Health pool, a DamageCalculator that turns attacker/defender stats into a
 * final damage number with armor mitigation and deterministic crits, and a CombatSystem
 * that applies a strike and reports kills. The calculator is pure; the combat system owns
 * the side effects.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Health {
  constructor(max) { this.max = max; this.current = max; }
  damage(n) { this.current = Math.max(0, this.current - n); return this.current; }
  heal(n) { this.current = Math.min(this.max, this.current + n); return this.current; }
  get dead() { return this.current <= 0; }
}

class DamageCalculator {
  compute(attacker, defender, roll) {                 // roll in [0,1)
    const raw = Math.max(1, attacker.attack - Math.floor(defender.defense / 2));
    return roll >= attacker.critAt ? raw * 2 : raw;
  }
}

class CombatSystem {
  constructor(calc) { this.calc = calc; this.log = []; }
  strike(attacker, defender, defenderHealth, roll = 0) {
    const dmg = this.calc.compute(attacker, defender, roll);
    defenderHealth.damage(dmg);
    const killed = defenderHealth.dead;
    this.log.push({ dmg, killed });
    return { dmg, killed };
  }
}

// --- self-checking demo ---
const calc = new DamageCalculator();
const combat = new CombatSystem(calc);
const orc = { attack: 10, defense: 4, critAt: 0.9 };
const knight = { attack: 8, defense: 6, critAt: 0.9 };
const knightHp = new Health(30);

let r = combat.strike(orc, knight, knightHp, 0.1);
assert(r.dmg === 7, 'normal damage = attack - floor(defense/2)');     // 10 - 3
assert(knightHp.current === 23, 'health drops by the damage dealt');
r = combat.strike(orc, knight, knightHp, 0.95);
assert(r.dmg === 14, 'a crit doubles the damage');
assert(knightHp.current === 9, 'health now reduced to 9');
r = combat.strike(orc, knight, knightHp, 0.95);
assert(r.killed && knightHp.dead, 'a lethal blow reports a kill');
console.log('rpg/combat-damage OK');
```

```javascript
/**
 * RPG inventory + equipment: an Inventory that stacks items, an Equipment system that
 * moves gear between the inventory and equip slots while applying stat modifiers, and a
 * Character whose effective stats reflect what is equipped. The systems talk only through
 * method calls — none reaches into another's fields.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Inventory {
  constructor() { this.slots = new Map(); }            // id -> { item, qty }
  add(item, qty = 1) {
    const e = this.slots.get(item.id);
    if (e) e.qty += qty; else this.slots.set(item.id, { item, qty });
    return this;
  }
  remove(id, qty = 1) {
    const e = this.slots.get(id);
    if (!e || e.qty < qty) return null;
    e.qty -= qty;
    if (e.qty === 0) this.slots.delete(id);
    return e.item;
  }
  has(id) { return this.slots.has(id); }
  count(id) { const e = this.slots.get(id); return e ? e.qty : 0; }
}

class Equipment {
  constructor(inventory) { this.inv = inventory; this.worn = new Map(); }   // slot -> item
  equip(id) {
    const item = this.inv.remove(id, 1);
    if (!item) return false;
    const prev = this.worn.get(item.slot);
    if (prev) this.inv.add(prev, 1);                   // swap old gear back into the bag
    this.worn.set(item.slot, item);
    return true;
  }
  unequip(slot) {
    const item = this.worn.get(slot);
    if (!item) return false;
    this.worn.delete(slot);
    this.inv.add(item, 1);
    return true;
  }
  bonus(stat) {
    let total = 0;
    for (const item of this.worn.values()) total += (item.mods && item.mods[stat]) || 0;
    return total;
  }
}

class Character {
  constructor(base, equipment) { this.base = base; this.equipment = equipment; }
  stat(name) { return (this.base[name] || 0) + this.equipment.bonus(name); }
}

// --- self-checking demo ---
const inv = new Inventory();
const equip = new Equipment(inv);
const hero = new Character({ attack: 5, defense: 2 }, equip);
const sword = { id: 'sword', slot: 'hand', mods: { attack: 4 } };
const shield = { id: 'shield', slot: 'offhand', mods: { defense: 3 } };
inv.add(sword).add(shield);

assert(hero.stat('attack') === 5, 'base attack before equipping');
equip.equip('sword');
assert(hero.stat('attack') === 9, 'attack rises with equipped sword');
assert(!inv.has('sword'), 'equipped item leaves the inventory');
equip.equip('shield');
assert(hero.stat('defense') === 5, 'defense rises with equipped shield');
equip.unequip('hand');
assert(hero.stat('attack') === 5, 'attack returns to base after unequip');
assert(inv.has('sword'), 'unequipped item returns to the inventory');
console.log('rpg/inventory-equipment OK');
```

```javascript
/**
 * RPG progression: an ExperienceTrack with a rising XP curve, a LevelUp system that grants
 * stat growth for each level gained, and a Character the growth is applied to. A single XP
 * award can cross multiple levels at once. The track reports levels gained; the LevelUp
 * system owns how stats grow.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class ExperienceTrack {
  constructor() { this.level = 1; this.xp = 0; }
  needed(level) { return level * 100; }               // xp to advance from `level` to level+1
  add(amount) {
    this.xp += amount;
    let gained = 0;
    while (this.xp >= this.needed(this.level)) {
      this.xp -= this.needed(this.level);
      this.level += 1;
      gained += 1;
    }
    return gained;
  }
}

class LevelUp {
  constructor(growth) { this.growth = growth; }       // { hp: +n, attack: +n }
  apply(character, levels) {
    for (let i = 0; i < levels; i++)
      for (const k in this.growth) character.stats[k] += this.growth[k];
  }
}

class Character {
  constructor(stats) { this.stats = stats; }
}

// --- self-checking demo ---
const track = new ExperienceTrack();
const levelup = new LevelUp({ hp: 10, attack: 2 });
const hero = new Character({ hp: 50, attack: 5 });

let gained = track.add(100);                          // exactly enough for level 1 -> 2
assert(gained === 1 && track.level === 2, 'one level gained at 100 xp');
levelup.apply(hero, gained);
assert(hero.stats.hp === 60 && hero.stats.attack === 7, 'stat growth applied once');

gained = track.add(450);                              // need(2)=200 -> level 3, 250 xp left
assert(track.level === 3 && gained === 1, 'crossed to level 3');
levelup.apply(hero, gained);
assert(hero.stats.hp === 70, 'stats grow again on the new level');
console.log('rpg/leveling-xp OK');
```

```javascript
/**
 * Action collision: a SpatialHash that buckets entities into grid cells so only nearby
 * pairs are tested (broad phase), plus an axis-aligned bounding-box overlap test (narrow
 * phase). A CollisionSystem queries the hash and returns colliding pairs. The two phases
 * are separate so either can change without the other.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

function overlaps(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

class SpatialHash {
  constructor(cell) { this.cell = cell; this.buckets = new Map(); }
  key(cx, cy) { return cx + ',' + cy; }
  insert(e) {
    const k = this.key(Math.floor(e.x / this.cell), Math.floor(e.y / this.cell));
    if (!this.buckets.has(k)) this.buckets.set(k, []);
    this.buckets.get(k).push(e);
  }
  near(e) {
    const out = [];
    const cx = Math.floor(e.x / this.cell), cy = Math.floor(e.y / this.cell);
    for (let dx = -1; dx <= 1; dx++)
      for (let dy = -1; dy <= 1; dy++) {
        const b = this.buckets.get(this.key(cx + dx, cy + dy));
        if (b) for (const o of b) if (o !== e) out.push(o);
      }
    return out;
  }
}

class CollisionSystem {
  constructor(hash) { this.hash = hash; }
  pairs() {
    const seen = new Set(), result = [];
    for (const bucket of this.hash.buckets.values())
      for (const e of bucket)
        for (const o of this.hash.near(e)) {
          const id = e.id < o.id ? e.id + '|' + o.id : o.id + '|' + e.id;
          if (seen.has(id)) continue;
          seen.add(id);
          if (overlaps(e, o)) result.push([e.id, o.id]);
        }
    return result;
  }
}

// --- self-checking demo ---
const hash = new SpatialHash(32);
const a = { id: 'a', x: 10, y: 10, w: 10, h: 10 };
const b = { id: 'b', x: 15, y: 12, w: 10, h: 10 };               // overlaps a
const c = { id: 'c', x: 200, y: 200, w: 10, h: 10 };            // far away
[a, b, c].forEach(e => hash.insert(e));

assert(overlaps(a, b) && !overlaps(a, c), 'aabb test: a overlaps b but not c');
const sys = new CollisionSystem(hash);
const found = sys.pairs();
assert(found.length === 1, 'broad+narrow phase find exactly one pair');
assert(found[0].includes('a') && found[0].includes('b'), 'the colliding pair is a and b');
assert(hash.near(c).length === 0, 'the distant entity has no neighbours to test');
console.log('action/collision-grid OK');
```

```javascript
/**
 * Action spawning: an EnemyPool that recycles enemy objects instead of allocating, a
 * Spawner that releases enemies on a ramping interval, and a Wave value that shortens the
 * interval over time. The spawner asks the pool for instances; the pool owns reuse and
 * nothing is shared through globals.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class EnemyPool {
  constructor() { this.free = []; this.live = []; this.created = 0; }
  acquire(kind) {
    let e = this.free.pop();
    if (!e) { e = { kind: null, hp: 0, alive: false }; this.created += 1; }
    e.kind = kind; e.hp = 10; e.alive = true;
    this.live.push(e);
    return e;
  }
  release(e) {
    e.alive = false;
    const i = this.live.indexOf(e);
    if (i >= 0) this.live.splice(i, 1);
    this.free.push(e);
  }
}

class Spawner {
  constructor(pool, baseInterval) { this.pool = pool; this.base = baseInterval; this.t = 0; this.spawned = 0; }
  interval(wave) { return Math.max(1, this.base - wave); }   // each wave spawns faster
  tick(wave) {
    this.t += 1;
    if (this.t >= this.interval(wave)) {
      this.t = 0;
      this.spawned += 1;
      return this.pool.acquire('grunt');
    }
    return null;
  }
}

// --- self-checking demo ---
const pool = new EnemyPool();
const spawner = new Spawner(pool, 5);

let spawns = 0;
for (let i = 0; i < 5; i++) if (spawner.tick(0)) spawns += 1;     // interval 5 -> one spawn
assert(spawns === 1, 'one enemy spawned in five ticks at wave 0');
assert(pool.live.length === 1 && pool.created === 1, 'pool allocated exactly one enemy');

pool.release(pool.live[0]);                                       // enemy dies, returns to pool
for (let i = 0; i < 4; i++) spawner.tick(1);                      // wave 1 interval 4 -> one spawn
assert(pool.created === 1, 'next spawn reuses the pooled enemy, no new allocation');
assert(spawner.interval(3) < spawner.interval(0), 'higher waves spawn faster');
console.log('action/enemy-spawner OK');
```

```javascript
/**
 * Action scoring: a ComboMeter that grows while hits land inside a timing window and resets
 * when the window lapses, and a Score that awards points scaled by the meter's multiplier.
 * Score asks the meter for the current factor; the meter never touches the score.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class ComboMeter {
  constructor(windowMs) { this.window = windowMs; this.count = 0; this.last = -Infinity; }
  hit(now) {
    if (now - this.last <= this.window) this.count += 1; else this.count = 1;
    this.last = now;
    return this.count;
  }
  multiplier() { return 1 + Math.floor(this.count / 5); }       // +1x for every 5-combo
}

class Score {
  constructor(meter) { this.meter = meter; this.value = 0; }
  award(base, now) {
    this.meter.hit(now);
    this.value += base * this.meter.multiplier();
    return this.value;
  }
}

// --- self-checking demo ---
const meter = new ComboMeter(1000);
const score = new Score(meter);

score.award(10, 0);                                              // combo 1, x1 -> +10
assert(score.value === 10, 'first hit scores at x1');
for (let t = 200; t <= 800; t += 200) score.award(10, t);       // combos 2..5 inside window
assert(meter.count === 5, 'combo reaches five with rapid hits');
score.award(10, 1000);                                          // combo 6, x2 -> +20
assert(meter.multiplier() === 2, 'multiplier is x2 at a 6-combo');
const before = score.value;
score.award(10, 5000);                                          // window lapsed -> reset
assert(meter.count === 1, 'combo resets after a long gap');
assert(score.value === before + 10, 'the reset hit scores back at x1');
console.log('action/scoring-combo OK');
```

```javascript
/**
 * Adventure dialogue: a Flags store of world booleans, and a DialogueTree of nodes whose
 * choices branch to other nodes and can set flags or require them. Choosing an option
 * advances the tree and writes through to Flags — the tree keeps no global state of its own.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Flags {
  constructor() { this.map = new Map(); }
  set(name, val = true) { this.map.set(name, val); }
  get(name) { return this.map.get(name) || false; }
}

class DialogueTree {
  constructor(nodes, flags) { this.nodes = nodes; this.flags = flags; this.current = 'start'; }
  node() { return this.nodes[this.current]; }
  choices() {
    return this.node().choices.filter(c => !c.requires || this.flags.get(c.requires));
  }
  choose(index) {
    const c = this.choices()[index];
    if (!c) return false;
    if (c.sets) this.flags.set(c.sets);
    this.current = c.to;
    return true;
  }
  get done() { return this.node().choices.length === 0; }
}

// --- self-checking demo ---
const flags = new Flags();
const nodes = {
  start: { text: 'A guard blocks the gate.', choices: [
    { text: 'Bribe him', to: 'bribed', sets: 'paidGuard' },
    { text: 'Sneak past', to: 'caught' },
  ] },
  bribed: { text: 'He steps aside.', choices: [
    { text: 'Enter', to: 'inside', requires: 'paidGuard' },
  ] },
  caught: { text: 'You are caught.', choices: [] },
  inside: { text: 'You are inside.', choices: [] },
};
const dlg = new DialogueTree(nodes, flags);

assert(dlg.choices().length === 2, 'two choices are available at the start');
dlg.choose(0);                                                  // bribe -> sets flag, advances
assert(flags.get('paidGuard'), 'bribing sets the world flag');
assert(dlg.current === 'bribed', 'tree advanced to the bribed node');
assert(dlg.choices().length === 1, 'the flag unlocks the gated choice');
dlg.choose(0);
assert(dlg.current === 'inside' && dlg.done, 'reached a terminal node');
console.log('adventure/dialogue-tree OK');
```

```javascript
/**
 * Adventure deduction: a Journal that records discovered clues (ignoring duplicates) and a
 * Mystery that unlocks its conclusion only when every required clue is present.
 * Investigation writes clues to the journal; the mystery reads them but never edits the
 * journal.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Journal {
  constructor() { this.clues = new Set(); this.order = []; }
  record(id) { if (!this.clues.has(id)) { this.clues.add(id); this.order.push(id); } }
  has(id) { return this.clues.has(id); }
  get count() { return this.clues.size; }
}

class Mystery {
  constructor(journal, required, conclusion) {
    this.journal = journal; this.required = required; this.conclusion = conclusion; this.solved = false;
  }
  missing() { return this.required.filter(id => !this.journal.has(id)); }
  trySolve() {
    if (this.missing().length === 0) this.solved = true;
    return this.solved ? this.conclusion : null;
  }
}

// --- self-checking demo ---
const journal = new Journal();
const mystery = new Mystery(journal, ['footprint', 'letter', 'witness'], 'The butler did it.');

journal.record('footprint');
journal.record('footprint');                                   // duplicate ignored
assert(journal.count === 1, 'a duplicate clue is not counted twice');
assert(mystery.trySolve() === null, 'the mystery cannot be solved early');
assert(mystery.missing().length === 2, 'two required clues are still missing');
journal.record('letter');
journal.record('witness');
assert(mystery.trySolve() === 'The butler did it.', 'the conclusion unlocks with all clues');
assert(mystery.solved, 'the mystery is marked solved');
console.log('adventure/journal-clues OK');
```

```javascript
/**
 * Adventure navigation: a RoomGraph of connected rooms with optionally locked exits, an
 * Inventory of keys, and a Navigator that moves the player between rooms, consulting the
 * inventory to pass locked doors and consuming the key when it does. The graph and the
 * inventory stay independent; the navigator coordinates them.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Inventory {
  constructor() { this.items = new Set(); }
  add(id) { this.items.add(id); }
  has(id) { return this.items.has(id); }
  take(id) { return this.items.delete(id); }
}

class RoomGraph {
  constructor(rooms) { this.rooms = rooms; }
  exit(room, dir) {
    const r = this.rooms[room];
    return (r && r.exits[dir]) || null;
  }
}

class Navigator {
  constructor(graph, inventory, start) { this.graph = graph; this.inv = inventory; this.room = start; }
  move(dir) {
    const exit = this.graph.exit(this.room, dir);
    if (!exit) return { ok: false, reason: 'no exit' };
    if (exit.locked && !this.inv.has(exit.key)) return { ok: false, reason: 'locked' };
    if (exit.locked) this.inv.take(exit.key);                   // the key is used up
    this.room = exit.to;
    return { ok: true, reason: 'moved' };
  }
}

// --- self-checking demo ---
const graph = new RoomGraph({
  hall: { exits: { north: { to: 'vault', locked: true, key: 'goldKey' }, east: { to: 'library' } } },
  library: { exits: { west: { to: 'hall' } } },
  vault: { exits: {} },
});
const inv = new Inventory();
const nav = new Navigator(graph, inv, 'hall');

assert(nav.move('north').reason === 'locked', 'the vault is locked without the key');
assert(nav.move('east').ok && nav.room === 'library', 'an open exit moves the player');
nav.move('west');                                              // back to the hall
inv.add('goldKey');
assert(nav.move('north').ok && nav.room === 'vault', 'the key opens the locked vault');
assert(!inv.has('goldKey'), 'the key is consumed when used');
console.log('adventure/world-rooms OK');
```

```javascript
/**
 * Casual run state: a Lives counter that ends the run at zero, a Score with a tracked best,
 * and a GameState machine the two feed into. Losing the last life flips the state to
 * game-over; the state machine reads the systems but they never reach into it.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Lives {
  constructor(n) { this.count = n; }
  lose() { this.count = Math.max(0, this.count - 1); return this.count; }
  get gameOver() { return this.count === 0; }
}

class Score {
  constructor() { this.value = 0; this.best = 0; }
  add(n) { this.value += n; if (this.value > this.best) this.best = this.value; return this.value; }
  reset() { this.value = 0; }
}

class GameState {
  constructor(lives, score) { this.lives = lives; this.score = score; this.phase = 'playing'; }
  update() {
    if (this.lives.gameOver) this.phase = 'gameover';
    return this.phase;
  }
}

// --- self-checking demo ---
const lives = new Lives(3);
const score = new Score();
const state = new GameState(lives, score);

score.add(100);
assert(score.best === 100, 'best score tracks the running total');
lives.lose(); lives.lose();
assert(state.update() === 'playing', 'still playing with one life left');
lives.lose();
assert(state.update() === 'gameover', 'game over once lives reach zero');
score.reset();
assert(score.value === 0 && score.best === 100, 'a reset clears the score but keeps the best');
console.log('casual/lives-score OK');
```

```javascript
/**
 * Casual match-3: a Board grid with match detection (runs of 3+), clearing, gravity, and
 * refill from an injected deterministic RNG, plus a Score that reacts to cleared tiles. The
 * board reports how many tiles it cleared; scoring lives in its own system and the RNG is
 * passed in so the board stays testable.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

function mulberry32(seed) {                                     // small deterministic PRNG
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

class Board {
  constructor(grid, rng, colors) {
    this.grid = grid; this.rng = rng; this.colors = colors;
    this.rows = grid.length; this.cols = grid[0].length;
  }
  findMatches() {
    const marks = new Set();
    const mark = (r, c) => marks.add(r + ',' + c);
    for (let r = 0; r < this.rows; r++)
      for (let c = 0; c < this.cols - 2; c++) {
        const v = this.grid[r][c];
        if (v != null && v === this.grid[r][c + 1] && v === this.grid[r][c + 2]) { mark(r, c); mark(r, c + 1); mark(r, c + 2); }
      }
    for (let c = 0; c < this.cols; c++)
      for (let r = 0; r < this.rows - 2; r++) {
        const v = this.grid[r][c];
        if (v != null && v === this.grid[r + 1][c] && v === this.grid[r + 2][c]) { mark(r, c); mark(r + 1, c); mark(r + 2, c); }
      }
    return marks;
  }
  clear(marks) {
    for (const k of marks) { const parts = k.split(','); this.grid[+parts[0]][+parts[1]] = null; }
    return marks.size;
  }
  collapse() {                                                 // gravity + refill per column
    for (let c = 0; c < this.cols; c++) {
      let write = this.rows - 1;
      for (let r = this.rows - 1; r >= 0; r--)
        if (this.grid[r][c] != null) { this.grid[write][c] = this.grid[r][c]; if (write !== r) this.grid[r][c] = null; write -= 1; }
      for (let r = write; r >= 0; r--) this.grid[r][c] = this.colors[Math.floor(this.rng() * this.colors.length)];
    }
  }
}

class Score {
  constructor() { this.value = 0; }
  cleared(n) { this.value += n * 10; return this.value; }
}

// --- self-checking demo ---
const grid = [
  ['r', 'g', 'b'],
  ['r', 'g', 'y'],
  ['r', 'y', 'b'],                                             // column 0 is r,r,r -> a match
];
const board = new Board(grid, mulberry32(42), ['r', 'g', 'b', 'y']);
const score = new Score();

const matches = board.findMatches();
assert(matches.size === 3, 'three tiles match down column 0');
score.cleared(board.clear(matches));
assert(score.value === 30, 'score is three cleared tiles x10');
board.collapse();
let full = true;
for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++) if (board.grid[r][c] == null) full = false;
assert(full, 'gravity and refill leave no empty cells');
console.log('casual/match3-board OK');
```

```javascript
/**
 * Casual power-ups: a Timer that advances and fires one-shot alarms, and a PowerUpSystem
 * that activates timed effects and removes them when their alarm elapses. Effects schedule
 * themselves on the timer; the timer knows nothing about what an effect does.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Timer {
  constructor() { this.now = 0; this.alarms = []; }
  at(delay, cb) { this.alarms.push({ time: this.now + delay, cb, done: false }); }
  advance(dt) {
    this.now += dt;
    for (const a of this.alarms) if (!a.done && this.now >= a.time) { a.done = true; a.cb(); }
    this.alarms = this.alarms.filter(a => !a.done);
  }
}

class PowerUpSystem {
  constructor(timer) { this.timer = timer; this.active = new Set(); }
  activate(name, duration) {
    this.active.add(name);
    this.timer.at(duration, () => this.active.delete(name));
  }
  has(name) { return this.active.has(name); }
}

// --- self-checking demo ---
const timer = new Timer();
const power = new PowerUpSystem(timer);

power.activate('shield', 300);
assert(power.has('shield'), 'the power-up is active immediately');
timer.advance(200);
assert(power.has('shield'), 'it is still active before its duration elapses');
timer.advance(150);                                            // total 350 > 300
assert(!power.has('shield'), 'it expires once the duration passes');
assert(timer.alarms.length === 0, 'the elapsed alarm is cleaned up');
console.log('casual/powerup-timer OK');
