```javascript
/**
 * Simulation economy: a Wallet holding currency, a Market that prices goods from supply, an
 * Inventory of owned goods, and a Store that ties them together — a purchase quotes the
 * Market, debits the Wallet, and deposits into the Inventory (selling reverses it and
 * returns stock to the Market). Each system owns one concern; they communicate only through
 * the Store. This is the economy -> store -> inventory chain.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Wallet {
  constructor(balance) { this.balance = balance; }
  canAfford(n) { return this.balance >= n; }
  debit(n) { if (!this.canAfford(n)) return false; this.balance -= n; return true; }
  credit(n) { this.balance += n; }
}

class Inventory {
  constructor() { this.goods = new Map(); }
  add(id, qty) { this.goods.set(id, this.count(id) + qty); }
  remove(id, qty) { if (this.count(id) < qty) return false; this.goods.set(id, this.count(id) - qty); return true; }
  count(id) { return this.goods.get(id) || 0; }
}

class Market {
  constructor(base) { this.base = base; this.stock = new Map(); }     // id -> units available
  setStock(id, units) { this.stock.set(id, units); }
  units(id) { const u = this.stock.get(id); return u == null ? 50 : u; }
  price(id) {
    const base = this.base[id] || 1;
    return Math.round(base * (50 / Math.max(1, this.units(id))));       // scarcer -> pricier
  }
}

class Store {
  constructor(wallet, market, inventory) { this.wallet = wallet; this.market = market; this.inv = inventory; }
  buy(id, qty) {
    const cost = this.market.price(id) * qty;
    if (!this.wallet.debit(cost)) return { ok: false, cost };
    this.inv.add(id, qty);
    this.market.setStock(id, this.market.units(id) - qty);
    return { ok: true, cost };
  }
  sell(id, qty) {
    if (!this.inv.remove(id, qty)) return { ok: false };
    const gain = this.market.price(id) * qty;
    this.wallet.credit(gain);
    this.market.setStock(id, this.market.units(id) + qty);
    return { ok: true, gain };
  }
}

// --- self-checking demo ---
const wallet = new Wallet(1000);
const market = new Market({ ore: 10 });
market.setStock('ore', 50);
const inv = new Inventory();
const store = new Store(wallet, market, inv);

assert(market.price('ore') === 10, 'price equals base at neutral stock');
const buy = store.buy('ore', 10);
assert(buy.ok && buy.cost === 100, 'bought ten ore for one hundred');
assert(wallet.balance === 900, 'the wallet was debited');
assert(inv.count('ore') === 10, 'the inventory received the ore');
assert(market.price('ore') > 10, 'the price rose as market stock fell');
const sell = store.sell('ore', 5);
assert(sell.ok && inv.count('ore') === 5, 'sold five ore back to the market');
assert(wallet.balance > 900, 'the wallet was credited from the sale');
console.log('simulation/economy-market OK');
```

```javascript
/**
 * Simulation production: a ResourceStore of goods, a Recipe describing inputs -> outputs,
 * and a Producer that each tick consumes inputs from the store and yields outputs when it
 * can, stalling cleanly when inputs run short. The store is the only shared surface; the
 * producer never mutates anything it doesn't own.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class ResourceStore {
  constructor(initial) { this.amounts = new Map(Object.entries(initial || {})); }
  get(id) { return this.amounts.get(id) || 0; }
  add(id, n) { this.amounts.set(id, this.get(id) + n); }
  take(id, n) { if (this.get(id) < n) return false; this.amounts.set(id, this.get(id) - n); return true; }
  canTake(map) { for (const id in map) if (this.get(id) < map[id]) return false; return true; }
}

class Recipe {
  constructor(inputs, outputs) { this.inputs = inputs; this.outputs = outputs; }
}

class Producer {
  constructor(store, recipe) { this.store = store; this.recipe = recipe; this.made = 0; }
  tick() {
    if (!this.store.canTake(this.recipe.inputs)) return false;
    for (const id in this.recipe.inputs) this.store.take(id, this.recipe.inputs[id]);
    for (const id in this.recipe.outputs) this.store.add(id, this.recipe.outputs[id]);
    this.made += 1;
    return true;
  }
}

// --- self-checking demo ---
const store = new ResourceStore({ ore: 5, coal: 5 });
const smelt = new Recipe({ ore: 2, coal: 1 }, { ingot: 1 });
const producer = new Producer(store, smelt);

assert(producer.tick(), 'the first smelt runs');
assert(store.get('ore') === 3 && store.get('coal') === 4, 'inputs were consumed');
assert(store.get('ingot') === 1, 'an output was produced');
let runs = 1;
while (producer.tick()) runs += 1;                             // continue until ore runs short
assert(runs === 2, 'production stops when an input runs short');
assert(producer.made === 2, 'two ingots were made in total');
assert(store.get('ore') === 1, 'leftover ore is below the recipe cost');
console.log('simulation/production-chain OK');
```

```javascript
/**
 * Simulation time: a Clock that accumulates minutes into hours and days, a DayNight phase
 * derived from the hour, and a Scheduler that fires one-shot events at target times. The
 * clock advances; the phase and scheduler read it without modifying it.
 */
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class Clock {
  constructor() { this.minute = 0; this.hour = 0; this.day = 0; }
  advance(minutes) {
    this.minute += minutes;
    while (this.minute >= 60) { this.minute -= 60; this.hour += 1; }
    while (this.hour >= 24) { this.hour -= 24; this.day += 1; }
  }
  totalMinutes() { return (this.day * 24 + this.hour) * 60 + this.minute; }
}

class DayNight {
  phase(hour) {
    if (hour < 6) return 'night';
    if (hour < 12) return 'morning';
    if (hour < 18) return 'afternoon';
    return 'evening';
  }
}

class Scheduler {
  constructor(clock) { this.clock = clock; this.events = []; }
  at(day, hour, cb) { this.events.push({ when: (day * 24 + hour) * 60, cb, fired: false }); }
  poll() {
    const now = this.clock.totalMinutes();
    let fired = 0;
    for (const e of this.events) if (!e.fired && now >= e.when) { e.fired = true; e.cb(); fired += 1; }
    return fired;
  }
}

// --- self-checking demo ---
const clock = new Clock();
const cycle = new DayNight();
const scheduler = new Scheduler(clock);

let rang = 0;
scheduler.at(0, 8, () => { rang += 1; });                      // an event at 08:00 on day 0

clock.advance(60 * 7);                                         // 07:00
assert(clock.hour === 7 && cycle.phase(clock.hour) === 'morning', 'it is morning at 7am');
assert(scheduler.poll() === 0, 'the event is not due yet');
clock.advance(120);                                           // 09:00
assert(scheduler.poll() === 1 && rang === 1, 'the event fires once past 08:00');
assert(scheduler.poll() === 0, 'the one-shot event does not fire again');
clock.advance(60 * 20);                                       // +20h -> rolls into the next day
assert(clock.day === 1, 'the day advances after 24 hours');
console.log('simulation/time-cycle OK');
```

