```javascript
function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

class ComboMeter { constructor(w){this.window=w;this.count=0;this.last=-Infinity;} hit(now){if(now-this.last<=this.window)this.count+=1;else this.count=1;this.last=now;return this.count;} multiplier(){return 1+Math.floor(this.count/5);} }
class Score { constructor(m){this.meter=m;this.value=0;} award(base,now){this.meter.hit(now);this.value+=base*this.meter.multiplier();return this.value;} }
const meter=new ComboMeter(750), score=new Score(meter);
score.award(10,0);
assert(score.value===10 && meter.count===1, 'first hit scores at x1');
for(let t=100;t<=500;t+=100) score.award(10,t);
assert(meter.count>=5, 'rapid hits build the combo past the step');
assert(meter.multiplier()>=2, 'multiplier rises with the combo');
const before=score.value;
score.award(10,100000);
assert(meter.count===1, 'a long gap resets the combo');
assert(score.value===before+10, 'the reset hit scores at x1 again');
console.log('gen scoring fantasy/normal OK');
```

